<?php defined( 'ABSPATH' ) || exit; ?>
<?php /** Atelier: chaque réponse reste une unité sémantique autonome et citable. */ ?>
<article id="bbp-reply-<?php bbp_reply_id(); ?>" class="atelier-reply" data-reply-id="<?php bbp_reply_id(); ?>">
	<aside class="atelier-avatar" style="background:<?php echo esc_attr( atelier_avatar_color( bbp_get_reply_author_id() ) ); ?>" aria-label="<?php echo esc_attr( bbp_get_reply_author_display_name() ); ?>"><?php echo esc_html( atelier_initials( bbp_get_reply_author_id() ) ); ?></aside>
	<div class="atelier-reply__body"><header class="atelier-post-meta"><span class="atelier-author"><?php bbp_reply_author_link( array( 'type' => 'name' ) ); ?></span><span class="atelier-rank"><?php echo esc_html( atelier_rank( bbp_get_reply_author_id() ) ); ?></span><time datetime="<?php echo esc_attr( get_post_time( DATE_W3C, true, bbp_get_reply_id() ) ); ?>"><?php bbp_reply_post_date(); ?></time></header><div class="atelier-reply__content"><?php bbp_reply_content(); ?></div><footer class="atelier-post-footer"><span>Réponse archivée</span><?php if ( class_exists( 'PFC_Community' ) ) : $reply_id = bbp_get_reply_id(); $voted = is_user_logged_in() && PFC_Community::has_voted( get_current_user_id(), $reply_id ); ?><button type="button" class="atelier-vote-button" data-pfc-vote data-object-id="<?php echo esc_attr( $reply_id ); ?>" data-login="<?php echo esc_url( wp_login_url( get_permalink( $reply_id ) ) ); ?>" aria-pressed="<?php echo $voted ? 'true' : 'false'; ?>"><span data-pfc-vote-label><?php echo $voted ? 'Vote ajouté' : 'Voter utile'; ?></span> <span data-pfc-vote-count><?php echo esc_html( atelier_total_upvotes( $reply_id ) ); ?></span></button><?php else : ?><span><?php echo esc_html( atelier_total_upvotes( bbp_get_reply_id() ) ); ?> votes utiles</span><?php endif; ?></footer></div>
</article>
